package org.slavicmyths.hellqa;
import java.util.*;import net.minecraft.gametest.framework.*;import net.minecraft.core.registries.Registries;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.Attributes;import net.minecraft.world.entity.projectile.AbstractArrow;import net.minecraft.world.item.*;import net.minecraft.world.item.enchantment.Enchantments;import net.neoforged.neoforge.gametest.*;import org.slavicmyths.nethersmithing.*;import org.slavicmyths.combat.WeaponProjectile;
@GameTestHolder("slavicmyths_hellqa") @PrefixGameTestTemplate(false)
public final class HellProjectileQaTests {
 @SuppressWarnings("unchecked") static Map<UUID,ServerPlayer> online(ServerPlayer p){try{var f=net.minecraft.server.players.PlayerList.class.getDeclaredField("playersByUUID");f.setAccessible(true);return (Map<UUID,ServerPlayer>)f.get(p.getServer().getPlayerList());}catch(Exception e){throw new RuntimeException(e);}}
 static net.minecraft.world.entity.animal.Cow target(GameTestHelper t,ServerPlayer p){var cow=EntityType.COW.create(t.getLevel());cow.setNoAi(true);cow.setNoGravity(true);cow.getAttribute(Attributes.MAX_HEALTH).setBaseValue(200);cow.setHealth(200);cow.moveTo(p.position().add(0,.5,3));t.getLevel().addFreshEntity(cow);return cow;}
 static AbstractArrow arrow(GameTestHelper t,ServerPlayer p,ItemStack bow){HellQaTests.check(p.getProjectile(bow).is(Items.ARROW),"No arrow ammunition before release");p.startUsingItem(InteractionHand.MAIN_HAND);try{bow.getItem().releaseUsing(bow,t.getLevel(),p,bow.getUseDuration(p)-24);}finally{p.stopUsingItem();}var arrows=t.getLevel().getEntitiesOfClass(AbstractArrow.class,p.getBoundingBox().inflate(8),a->a.getOwner()==p&&!a.isRemoved());HellQaTests.check(arrows.size()==1,"Expected one native arrow: "+arrows.size());var a=arrows.getFirst();HellQaTests.check(a.isCritArrow(),"Full-draw native critical flag lost");a.setCritArrow(false);return a;}
 @GameTest(template="empty") public static void nativeBowSkillOrdinaryAndPower(GameTestHelper t){var p=HellQaTests.player(t);var online=online(p);online.put(p.getUUID(),p);var target=target(t,p);try{var bow=HellQaTests.item("infernal_bow");p.setItemInHand(InteractionHand.MAIN_HAND,bow);p.getInventory().setItem(1,new ItemStack(Items.ARROW,64));p.setShiftKeyDown(true);var a=arrow(t,p,bow);HellQaTests.check(a.getPersistentData().getBoolean("InfernalSkill"),"Full sneak draw not special");a.tick();HellQaTests.check(target.getHealth()==187&&target.getRemainingFireTicks()>=160&&bow.getDamageValue()==4,"Special arrow actual damage/fire/wear "+target.getHealth()+" fire="+target.getRemainingFireTicks()+" wear="+bow.getDamageValue());a.discard();target.invulnerableTime=0;target.setRemainingFireTicks(0);var normal=arrow(t,p,bow);HellQaTests.check(!normal.getPersistentData().getBoolean("InfernalSkill"),"Cooldown still fired special");normal.tick();HellQaTests.check(target.getHealth()==177&&bow.getDamageValue()==5,"Ordinary arrow blocked/scaled during skill cooldown "+target.getHealth());normal.discard();target.invulnerableTime=0;p.setShiftKeyDown(false);bow.enchant(t.getLevel().registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(Enchantments.POWER),2);var powered=arrow(t,p,bow);powered.tick();// The pinned 1.21.1 native arrow/Power II impact is 14 HP (normal 10 HP); no owner-defined Power II total exists.
HellQaTests.check(target.getHealth()==163,"PowerII native modification must apply once (expected 14 HP from full-draw 10 HP), actual damage="+(177-target.getHealth()));powered.discard();HellQaTests.check(p.getInventory().countItem(Items.ARROW)==61,"Native ammo consumption mismatch");System.out.println("HELLQA_PASS real one-arrow special13/fire160/wear4; ordinary10 on CD; PowerII14 native verified; native ammo and crit flag");t.succeed();}finally{online.remove(p.getUUID());target.discard();}}
 @GameTest(template="empty") public static void actualKnifeProjectileOneItemAndLoyalty(GameTestHelper t){var p=HellQaTests.player(t);var online=online(p);online.put(p.getUUID(),p);var target=target(t,p);try{var knife=HellQaTests.item("shadow_throwing_knife");Item knifeItem=knife.getItem();knife.enchant(t.getLevel().registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(Enchantments.LOYALTY),3);p.setItemInHand(InteractionHand.MAIN_HAND,knife);p.setShiftKeyDown(true);knife.getItem().use(t.getLevel(),p,InteractionHand.MAIN_HAND);var shots=t.getLevel().getEntitiesOfClass(WeaponProjectile.class,p.getBoundingBox().inflate(8),a->a.getOwner()==p);HellQaTests.check(shots.size()==1&&p.getMainHandItem().isEmpty(),"Knife duplicated or not consumed");var shot=shots.getFirst();HellQaTests.check(shot.netherSkill()&&shot.getItem().getDamageValue()==3&&shot.loyalty()==3,"Knife owner components/skill/wear/Loyalty");for(int i=0;i<4&&!shot.isRemoved();i++)shot.tick();HellQaTests.check(target.getHealth()==190&&target.hasEffect(net.minecraft.world.effect.MobEffects.WEAKNESS),"Native knife hit/debuff failed "+target.getHealth());for(int i=0;i<100&&!shot.isRemoved();i++)shot.tick();HellQaTests.check(shot.isRemoved()&&p.getInventory().countItem(knifeItem)==1,"Loyalty did not return exactly one knife: removed="+shot.isRemoved()+" returned="+p.getInventory().countItem(knifeItem));var returned=p.getInventory().items.stream().filter(s->s.getItem()==knifeItem).findFirst().orElseThrow();HellQaTests.check(!NetherSkills.ready(p,returned,"shadow_throwing_knife")&&returned.getDamageValue()==3,"Returned knife lost carried cooldown/wear");System.out.println("HELLQA_PASS real knife projectile10/Weakness, one consumed and LoyaltyIII returned once with wear/stack cooldown");t.succeed();}finally{online.remove(p.getUUID());target.discard();}}
}
